//! Infra P32: quality, lifecycle, checksum, and locality integrity for research assets.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;
pub const CONTENT_TYPE:&str="application/vnd.aurora.infra.reliability-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct InfraAsset4{pub asset_id:String,pub tier:String,pub checksum:String,pub lifecycle:String,pub quality_milli:u32,pub quality_threshold_milli:u32,pub evidence_state:String,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReliabilityIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub assets:Vec<InfraAsset4>,pub required_asset_order:Vec<String>,pub required_tier_order:Vec<String>,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub asset_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReliabilityIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct ReliabilityIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub asset_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub tier_order:Vec<String>,pub lifecycle_order:Vec<String>,pub quality_order:Vec<String>,pub checksum_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:ReliabilityIntegrityArtifact4}
#[derive(Debug,Error)] pub enum ReliabilityIntegrityError{#[error("reliability integrity input is invalid: {0}")] Invalid(String),#[error("reliability integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}
fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}
fn invalid(v:impl Into<String>)->ReliabilityIntegrityError{ReliabilityIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"infra","consumers":["cache controller","quota scheduler","storage tier manager","operations service"],"behavior":format!("qualify research asset reliability at {scale} ({mode})"),"value":"prevents low-quality, expired, corrupt, or non-local assets from entering durable research workflows","input_schema":"ReliabilityIntegrityRequest4@1","output_schema":"ReliabilityIntegrityCard7@1","effects":["emit:reliability-card","retain:quality-witness","block:unsafe-asset"],"permissions":["read:local-asset-metadata"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&ReliabilityIntegrityCard7)->Result<(),ReliabilityIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.request_id.is_empty()||c.purpose.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("reliability identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.asset_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.tier_order,&c.lifecycle_order,&c.quality_order,&c.checksum_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("reliability vectors are not canonical"));}}let ids=c.asset_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("asset states do not partition assets"));}Ok(())}
pub fn qualify(q:&ReliabilityIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<ReliabilityIntegrityCard7,ReliabilityIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.assets.is_empty()||q.required_asset_order.is_empty()||!canonical(&q.required_asset_order)||!canonical(&q.required_tier_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.asset_budget==0{return Err(invalid("reliability identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.assets.clone();rows.sort_by(|a,b|a.asset_id.cmp(&b.asset_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut tiers=BTreeSet::new();let mut lifecycles=BTreeSet::new();let mut qualities=BTreeSet::new();let mut checksums=BTreeSet::new();let mut evidence=BTreeSet::new();for a in &rows{if a.asset_id.trim().is_empty()||!seen.insert(a.asset_id.clone())||a.tier.trim().is_empty()||!digest(&a.checksum)||a.lifecycle.trim().is_empty()||a.evidence_state.trim().is_empty()||a.quality_milli>1000||a.quality_threshold_milli>1000||!a.local||!a.aggregate_only{return Err(invalid("asset identity, tier, checksum, lifecycle, quality, evidence, or locality is invalid"));}tiers.insert(format!("{}:{}",a.asset_id,a.tier));lifecycles.insert(format!("{}:{}",a.asset_id,a.lifecycle));qualities.insert(format!("{}:{}:{}",a.asset_id,a.quality_milli,a.quality_threshold_milli));checksums.insert(format!("{}:{}",a.asset_id,a.checksum));evidence.insert(a.checksum.clone());if a.evidence_state=="unknown"||a.checksum==q.replay_identity{unknown.insert(a.asset_id.clone());}else if a.quality_milli<a.quality_threshold_milli||a.lifecycle=="expired"||a.lifecycle=="corrupt"{rejected.insert(a.asset_id.clone());}else if !q.required_asset_order.contains(&a.asset_id){omitted.insert(a.asset_id.clone());}else{accepted.insert(a.asset_id.clone());}}let missing=q.required_asset_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.asset_budget;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let asset_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"asset_order":asset_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"tier_order":tiers.into_iter().collect::<Vec<_>>(),"lifecycle_order":lifecycles.into_iter().collect::<Vec<_>>(),"quality_order":qualities.into_iter().collect::<Vec<_>>(),"checksum_order":checksums.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|ReliabilityIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:reliability:{}",q.request_id)]}else{vec!["block:unsafe-asset".into()]};let artifact=ReliabilityIntegrityArtifact4{artifact_id:format!("infra-reliability:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=ReliabilityIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),asset_order:body["asset_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,tier_order:body["tier_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),lifecycle_order:body["lifecycle_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),quality_order:body["quality_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),checksum_order:body["checksum_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
